import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { IArticleDetailModel } from '../../../../../data/model/article/ArticleDetailModel';
import { ArticleFilterModel, IArticleFilterModel } from '../../../../../data/model/article/ArticleFilterModel';
import { ArticleService } from '../../../../../data/service/article/article.service';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { IArticleModel } from '../../../../../data/model/article/ArticleModel';

@Component({
  selector: 'app-article-state',
  templateUrl: './article-state.component.html',
  styleUrls: ['./article-state.component.scss']
})
export class ArticleStateComponent implements OnInit {

  selectedArticleId = 0;
  selectedCategory = '2';
  selected = false;
  filteredArticles: IArticleFilterModel;
  selectedArticle: IArticleDetailModel;
  searchTitle = '';
  isEdited = false;

  constructor(
    private articleService: ArticleService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    let filter: IArticleFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page ? params.page : 1;
      const take = params.take ? params.take : 6;
      const title = params.title ? params.title : null;

      filter = new ArticleFilterModel(page, take, title);

      this.filteredArticles = filter;

      this.getDate(this.selectedCategory);
    });
  }

  categoryChanged() {

    this.getDate(this.selectedCategory);
  }

  getDate(type: string) {

    SharedIonic.loading(this.loadingController);

    switch (type) {
      case '1':
        this.articleService.GetArticlesByFilter(this.filteredArticles).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredArticles = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredArticles.articles = [];
            } else {
              SharedIonic.unSuccessToast(this.toastController);
              this.filteredArticles.articles = [];
            }
          },
          err => {
            this.filteredArticles.articles = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case '2':
        this.articleService.GetDeActiveArticlesByFilter(this.filteredArticles).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredArticles = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredArticles.articles = [];
            } else {
              this.filteredArticles.articles = [];
              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {
            this.filteredArticles.articles = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      case '3':
        this.articleService.GetEditArticlesByFilter(this.filteredArticles).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredArticles = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredArticles.articles = [];
            } else {
              this.filteredArticles.articles = [];
              SharedIonic.unSuccessToast(this.toastController);
            }
          },
          err => {
            this.filteredArticles.articles = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
      default:
        this.articleService.GetArticlesByFilter(this.filteredArticles).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {
              this.filteredArticles = res.data;
            } else if (res.status === GResponse.NotFoundStatus) {
              this.filteredArticles.articles = [];
            } else {
              SharedIonic.unSuccessToast(this.toastController);
              this.filteredArticles.articles = [];
            }
          },
          err => {
            this.filteredArticles.articles = [];
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        );
        break;
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredArticles.startPage == null) {
      return;
    }
    if (this.filteredArticles.pageId > this.filteredArticles.startPage && +this.filteredArticles.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredArticles.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredArticles.endPage == null) {
      return;
    }
    if (this.filteredArticles.pageId < this.filteredArticles.endPage) {
      this.setQueryParams(+this.filteredArticles.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredArticles.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'ArticleState'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredArticles.takeEntity ? this.filteredArticles.takeEntity : null,
            title: this.filteredArticles.title ? this.filteredArticles.title : null
          }
        });
  }

  onActiveEdit(): void {

    SharedIonic.loading(this.loadingController);

    this.articleService.ActiveArticleEditById(+this.selectedArticleId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onActive(): void {

    SharedIonic.loading(this.loadingController);

    this.articleService.ActiveArticleById(+this.selectedArticleId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onActiveNoShare(): void {

    SharedIonic.loading(this.loadingController);

    this.articleService.ActiveArticleByIdNoShare(+this.selectedArticleId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onDeActive(): void {

    SharedIonic.loading(this.loadingController);

    this.articleService.DeActiveArticleById(+this.selectedArticleId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          SharedIonic.successToast(this.toastController);
          this.selected = false;
          this.getDate(this.selectedCategory);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentActiveAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActive();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentActiveAlertConfirmNoShare() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActiveNoShare();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentEditAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActiveEdit();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentDeActiveAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به غیر فعال کردن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onDeActive();
          }
        }
      ]
    });

    await alert.present();
  }

  getTeacherName() {

    if (this.selectedArticle.teacherUser === undefined || this.selectedArticle.teacherUser == null) {

      return '';
    }
    const name = this.selectedArticle.teacherUser.name != null ? this.selectedArticle.teacherUser.name : '';
    const family = this.selectedArticle.teacherUser.family != null ? this.selectedArticle.teacherUser.family : '';

    return name + ' ' + family;
  }

  onSelectItem(model: IArticleModel) {

    this.selectedArticleId = +model.id;
    this.isEdited = this.filteredArticles.articles.find(e => e.id == +model.id).isEdited;

    SharedIonic.loading(this.loadingController);

    if (this.selectedCategory == '1') {

      this.articleService.GetArticleById(+this.selectedArticleId).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.selectedArticle = res.data;
            this.selectedArticle.imageUrl = this.filteredArticles.articles.find(e => e.id == +model.id).imageUrl;
            this.selected = true;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
    else {
      this.articleService.GetArticleEditById(+this.selectedArticleId).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.selectedArticle = res.data;
            this.selectedArticle.imageUrl = this.filteredArticles.articles.find(e => e.id == +model.id).imageUrl;
            this.selected = true;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
