import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { ArticleStateComponent } from './article-state.component';

const routes: Routes = [{ path: '', component: ArticleStateComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ArticleStateRoutingModule { }
